\end{itemize}
\section{Experience}
{\small
\resumeSubHeadingListStart

\resumeSubheading
  {Machine Learning Intern}{May 2025 -- August 2025}
  {Ayar Labs}{Santa Clara, CA}
  \resumeItemListStart
    \resumeItem{Quantified inline multi-modal AI stack for video performance by testing and helping in developing and optimizing algorithms through model evaluation cycles and error analysis, reducing validation failures to 3\% across 2,000 sampled video clips.}
    \resumeItem{Prototyped data science-driven deep learning improvements within the inline multi-modal AI stack for video by iterating on multimodal AI preprocessing and evaluation metrics, improving validation F1 by +6.2 points on a h.}
    \resumeItem{Strengthened low-latency inline video processing goals by tuning throughput and latency-critical inference optimization components for inline execution, cutting median inline inference latency from 120 ms to 78 ms (35\% reduction).}
  \resumeItemListEnd

\resumeSubheading
  {Machine Learning Intern}{July 2024 -- December 2024}
  {Indian Institute of Technology, Indore}{Indore, India}
  \resumeItemListStart
    \resumeItem{Facilitated collaboration with the Core AI team to iterate on inline video multimodal AI algorithm improvements, coordinating testing and validation, model evaluation, and statistical modeling to align 4 cross-functional stakeholders across 8 teams.}
    \resumeItem{Tuned neural network components for the inline multi-modal AI video stack, optimizing deep learning pipelines to achieve 3\% precision at 4\% recall on an imbalanced dataset.}
    \resumeItem{Accelerated data structures-driven algorithm optimization efforts to support low-latency inline video processing goals, improving memory efficiency and cutting the memory footprint by 46 MB.}
  \resumeItemListEnd

\resumeSubheading
  {Machine Learning Intern}{January 2024 -- June 2024}
  {National Institute of Technology, Jaipur}{Jaipur, India}
  \resumeItemListStart
    \resumeItem{Analyzed and executed algorithm test cycles using dedicated test harnesses to support iterative development of inline multi-modal video AI components, covering 23 service SLOs with unified alerting.}
    \resumeItem{Identified statistical analysis drivers for improving inline multi-modal video AI algorithms by applying statistical models to analyze data, quantifying error drivers, guiding model selection, and cutting dashboard load time from 18s to 6s.}
    \resumeItem{Integrated end-to-end integration of inline multi-modal video AI algorithm changes into the content fabric workflow, using statistics to validate evaluation-to-workflow handoff outputs while scaling from 9 to 119 repli.}
  \resumeItemListEnd

\resumeSubheading
  {Machine Learning Intern}{May 2023 -- December 2023}
  {Indian Institute of Technology, Indore}{Indore, India}
  \resumeItemListStart
    \resumeItem{Examined large-scale multimedia constraints in the inline video AI stack by applying algorithms and problem-solving techniques to improve multimedia processing throughput, improving BLEU score from 0.77 to 0.87 on the held-out test split.}
    \resumeItem{Programmed machine learning algorithms for cutting-edge deep learning projects, developing and optimizing statistical models to reduce pipeline failure rate from 4\% to under 1\%, minimizing manual intervention from 38 times/week to 11.}
    \resumeItem{Mapped inline multi-modal AI stack for video components using testing/validation and test harnesses, running algorithm test cycles to stabilize model evaluation across iterations.}
  \resumeItemListEnd

\resumeSubHeadingListEnd

